patch:
--- a/great-wave.html
+++ b/great-wave.html
@@ -235,6 +235,42 @@
         transition-duration: 0.01ms !important;
       }
     }
+  
+    .keyed-crop {
+      position: relative;
+      justify-self: center;
+      width: min(100%, 456px, calc((100svh - 13rem) * 0.6263736));
+      margin: 0;
+    }
+    .keyed-crop .detail-image { width: 100%; height: auto; }
+    .mark-key {
+      display: inline-grid;
+      place-items: center;
+      width: 1.35em;
+      height: 1.35em;
+      background: var(--ink);
+      color: var(--foam);
+      border: 1px solid var(--gold);
+      font: 700 0.84rem/1 "News Cycle", sans-serif;
+    }
+    .keyed-crop .mark-key {
+      position: absolute;
+      transform: translate(-50%, -50%);
+      pointer-events: none;
+    }
+    .source-title { left: 82%; top: 34%; }
+    .source-signature { left: 18%; top: 35%; }
+    .source-title::before, .source-signature::after {
+      content: "";
+      position: absolute;
+      background: var(--ink);
+    }
+    .source-title::before { right: 100%; width: .38rem; height: 1px; }
+    .source-signature::after { top: 100%; height: .38rem; width: 1px; }
+    .annotations dt .mark-key { margin-inline-end: 0.4em; vertical-align: 0.09em; }
+    @media (max-width: 650px) {
+      .keyed-crop { width: min(100%, calc(min(65svh, 560px) * 0.6263736)); }
+    }
   </style>
 </head>
 <body>
@@ -257,16 +293,20 @@

       <section class="detail-view" id="detail-view"
                aria-label="The inscriptions" hidden>
-        <img class="detail-image"
+        <figure class="keyed-crop">
+          <img class="detail-image"
              src="/fixture/wave-detail.webp" width="456" height="728"
              alt="Close-up of the upper-left corner of the print, showing a signature to the left and a rectangular title cartouche to the right.">
+          <span class="mark-key source-title" aria-hidden="true" data-source-key="title">A</span>
+          <span class="mark-key source-signature" aria-hidden="true" data-source-key="signature">B</span>
+        </figure>

         <div class="annotations">
           <h2>The inscriptions</h2>
           <dl>
-            <dt>Title cartouche</dt>
+            <dt data-reading-key="title"><span class="mark-key" aria-hidden="true">A</span>Title cartouche</dt>
             <dd>The rectangle names the series <i>Thirty-six Views of Mount Fuji</i> and the print <i>Under the Wave off Kanagawa</i>.</dd>
-            <dt>Signature</dt>
+            <dt data-reading-key="signature"><span class="mark-key" aria-hidden="true">B</span>Signature</dt>
             <dd>To its left, the signature says that Hokusai is now working under the name Iitsu.</dd>
           </dl>
